-- Projekt editorial JSON candidates
-- Generated: 2026-06-25
-- Imports disabled _iss_editorial_projekt documents for all published projekt posts.
-- Documents include optional projekt_rail sections and structured massstab facts for visual review.
-- Frontend remains on legacy post_content until _iss_editorial_enabled_projekt is set to 1 per post.

START TRANSACTION;

DELETE FROM wp_postmeta
WHERE post_id IN (25720,25657,24819,24818,24817,24816,24815)
  AND meta_key IN ('_iss_editorial_projekt', '_iss_editorial_enabled_projekt', '_iss_editorial_projekt_autosave');


COMMIT;
